SELECT 'https://example.org/oulad/id/assessment-record/' || id_student || '/' || id_assessment AS record, 'https://example.org/oulad/id/enrollment/' || code_module || '/' || code_presentation || '/' || id_student AS enrollment, 'https://example.org/oulad/id/assessment/' || id_assessment AS assessment FROM student_assessment JOIN assessments USING(id_assessment) WHERE score IS NULL;
